class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    throw new Error("Method 'cast()' must be implemented by subclasses.");
  }

  describe() {
    throw new Error("Method 'describe()' must be implemented by subclasses.");
  }
}

class FireballSpell extends Spell {
  constructor(name, manaCost, damage) {
    super(name, manaCost);
    this.damage = damage;
  }

  cast() {
    return `A searing fireball erupts, dealing ${this.damage} damage!`;
  }

  describe() {
    return `${this.name}: Costs ${this.manaCost} mana, deals ${this.damage} damage.`;
  }
}

